python3 -I -c "
import json, glob
# find a training failure trace with timeout and inspect
for f in sorted(glob.glob('outputs/tool_events/*.json')):
    t=json.load(open(f))
    if t['split']=='inventory_train' and any(e.get('response')=='timeout' for e in t['result']['events']):
        print(f)
        print('scenario:', t['scenario_id'], 'qty:', t['result']['quantity'])
        for a in t['actions']:
            print(' turn',a['turn'],'->',a['policy_action'][:80])
        for e in t['result']['events']:
            if e['type']=='mutation':
                print('  mut:', e['action'], e['quantity'], 'attempt',e['attempt'], e['response'], 'delta', e.get('progress_delta'), 'ledger', e['ledger'])
            else:
                print('  receipt:', e['receipt'], 'correct:', e['correctness'])
        print('final ledger:', t['result']['ledger'], 'success:', t['result']['success'], 'reward:', t['result']['reward'])
        break
"

